const r = await tools.pwsh({
  description: "Inspect profile pnpm workspace config",
  command: `
Get-ChildItem 'C:\\Users\\jjq21\\.dsh\\profiles\\desktop' -Force | Select-Object Name | Format-Table -AutoSize | Out-String
Write-Output '--- pnpm-workspace.yaml ---'
try { Get-Content -Raw 'C:\\Users\\jjq21\\.dsh\\profiles\\desktop\\pnpm-workspace.yaml' } catch { 'ERR ' + $_.Exception.Message }
Write-Output '--- .npmrc ---'
try { Get-Content -Raw 'C:\\Users\\jjq21\\.dsh\\profiles\\desktop\\.npmrc' } catch { 'ERR ' + $_.Exception.Message }
`,
  timeoutMs: 60000,
});
if (r.kind === "foreground") console.log(r.stdout.text.slice(0, 3000));
